def choose_move(observation):
    w,h = observation['grid_width'], observation['grid_height']
    x,y = observation['self_position']
    obstacles = set(tuple(obs) for obs in observation['obstacles'])
    resources = observation['resources']
    opp_x, opp_y = observation['opponent_position']
    def safe_move(dx, dy):
        nx, ny = x + dx, y + dy
        return 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles
    directions = [(-1,0),(1,0),(0,-1),(0,1)]
    if resources:
        tx, ty = min(resources, key=lambda r: abs(r['x']-x)+abs(r['y']-y))
        dx = 0 if tx==x else (1 if tx>x else -1)
        dy = 0 if ty==y else (1 if ty>y else -1)
        if safe_move(dx,dy):
            return [dx, dy]
        for ddx, ddy in directions:
            if safe_move(ddx,ddy):
                return [ddx, ddy]
        return [0, 0]
    if abs(opp_x - x) + abs(opp_y - y) < 10:
        dx = -1 if opp_x > x else 1 if opp_x < x else 0
        dy = -1 if opp_y > y else 1 if opp_y < y else 0
        if safe_move(dx,dy):
            return [dx, dy]
    for ddx, ddy in directions:
        if safe_move(ddx, ddy):
            return [ddx, ddy]
    return [0, 0]
